<script setup lang="ts">
import { ArrowUpRight, ArrowRight, Snowflake, Leaf, Minus, Plus, MapPin, ChevronRight, X, Check, Zap, Ticket as TicketIcon } from 'lucide-vue-next'
import { money, bottleCount } from '~/shared/domain'
const shop = useShop()
const pickupInfo = ref(false)
const loading = ref(false)
const error = ref('')
const queue = ref<{ tag: string; name: string }[]>([])
const chosen = computed(() => shop.drops.value.find(d => d.id === shop.selected.value))
onMounted(async () => {
  loading.value = true
  try { await shop.refreshDrops(); if (!shop.demo) { const data = await $fetch<{ queue: { tag: string; name: string }[] }>('/api/catalog'); queue.value = data.queue; const latest = localStorage.getItem('tebu_latest_ticket'); if (latest && shop.customerToken.value) { try { const ticket = await $fetch<import('~/shared/domain').Ticket>(`/api/orders/${encodeURIComponent(latest)}`); shop.tickets.value = [ticket] } catch {} } } }
  catch { error.value = 'Could not load the drop schedule. Please refresh to try again.' }
  finally { loading.value = false }
})
function checkout() { if (!bottleCount(shop.cart.value)) return shop.notify('Add a flask or jug to get started.'); shop.checkoutOpen.value = true }
</script>
<template>
  <div class="home-page">
    <div class="intro-row"><span class="eyebrow"><span class="status-dot"></span> YOUR WEEKDAY REFRESH</span><button class="text-button" @click="pickupInfo = !pickupInfo">How it works <ArrowUpRight :size="13" /></button></div>
    <section class="hero">
      <div class="hero-copy"><span class="hero-kicker">PRESSED FRESH. FROZEN SOLID.</span><h1>A little cane.<br>A better<br><span>workday.</span></h1><p>Pure backyard sugarcane.<br>Cold-pressed. Nothing added.</p><div class="hero-tags"><span><Leaf :size="11"/> 100% pure</span><span><Snowflake :size="11"/> Always cold</span></div></div>
      <div class="hero-scene"><span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><span class="cane-stem stem-one"></span><span class="cane-stem stem-two"></span><BottleArt hero/><span class="fresh-sticker">NO SUGAR<br>JUST CANE <span>✳</span></span><span class="hero-spark">✳</span></div>
      <div class="hero-bottom"><span>FROM OUR BACKYARD TO YOUR PANTRY</span><span>↗</span></div>
    </section>
    <NuxtLink v-if="shop.activeTicket.value" class="active-ticket" :to="`/drop?t=${shop.activeTicket.value.token}`"><TicketIcon/><div><strong>Your {{ shop.activeTicket.value.tag }} is locked in</strong><span>View your bottle’s pickup ticket</span></div><ChevronRight :size="18"/></NuxtLink>
    <button class="pickup-strip" @click="pickupInfo = !pickupInfo"><span class="pickup-icon"><MapPin :size="18" /></span><span><strong>Your office. Your pickup spot.</strong><small>Level 7 pantry freezer · From 9:00 AM</small></span><ChevronRight :size="17" /></button>
    <section v-if="pickupInfo" class="info-card"><div class="section-heading"><h3>From cane to coffee break.</h3><button class="icon-button" @click="pickupInfo = false" aria-label="Close pickup instructions"><X :size="17" /></button></div><ol><li>Pick a drop day and choose your bottles.</li><li>Pay with DuitNow and upload your receipt.</li><li>After confirmation, find your numbered bag in the Level 7 pantry freezer from 9 AM.</li></ol><p>Keep frozen. Thaw in the fridge, shake well and enjoy cold. Collect on your chosen day.</p></section>
    <section class="schedule-section"><div class="section-heading"><h2>Pick your drop.</h2><span class="subtle">Mon – Thu, every week</span></div><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" class="subtle">Loading available drops…</p><div class="drop-days" role="group" aria-label="Pickup day"><button v-for="drop in shop.drops.value" :key="drop.id" :class="['drop-day', { selected: shop.selected.value === drop.id }]" :disabled="drop.remaining === 0" @click="shop.selected.value = drop.id"><span>{{ drop.day }}</span><strong>{{ drop.date }}</strong><small v-if="drop.remaining === 0">Sold out</small><small v-else><span v-if="shop.selected.value === drop.id" class="tiny-dot"></span>{{ shop.selected.value === drop.id ? 'Your drop' : shop.demo ? 'Available' : `${drop.remaining} left` }}</small></button></div></section>
    <section class="menu-section"><div class="section-heading"><h2>Goodness, bottled.</h2><span class="small-pill">NO ICE. NO DILUTION.</span></div><article v-for="product in shop.products.filter(p => p.kind === 'bottle')" :key="product.id" class="product-card"><div :class="['product-image', { 'jug-image': product.id === 'jug' }]"><BottleArt :jug="product.id === 'jug'"/><span class="volume-label">{{ product.size }}</span></div><div class="product-details"><span v-if="product.id === 'flask'" class="product-kicker">THE DAILY FAVOURITE</span><span v-else class="product-kicker">BETTER TOGETHER</span><h3>{{ product.name }}</h3><p>{{ product.description }}</p><div class="product-footer"><strong>{{ money(product.price) }}</strong><div class="quantity-control" v-if="shop.cart.value[product.id]"><button :aria-label="`Remove one ${product.name}`" @click="shop.change(product.id, -1)"><Minus :size="14" /></button><span aria-live="polite">{{ shop.cart.value[product.id] }}</span><button :disabled="shop.cart.value[product.id] >= 10" :aria-label="`Add one ${product.name}`" @click="shop.change(product.id, 1)"><Plus :size="14" /></button></div><button v-else class="add-button" :aria-label="`Add ${product.name}`" @click="shop.change(product.id, 1)"><Plus :size="17" /></button></div></div></article></section>
    <section class="addons"><div class="section-heading"><h2>Make it your own.</h2><span class="subtle">A little extra zing</span></div><div class="addon-grid"><article v-for="p in shop.products.filter(p => p.kind === 'addon')" :key="p.id" class="addon-card"><div :class="['fruit-art', p.id]"><span>{{ p.id === 'asam' ? '◉' : '◒' }}</span><span>{{ p.id === 'asam' ? '◉' : '◒' }}</span><i></i></div><div class="addon-title"><h3>{{ p.name }}</h3><span>+{{ money(p.price) }}</span></div><p>{{ p.description }}</p><div class="addon-bottom"><span>DIY ADD-ON POUCH</span><div v-if="shop.cart.value[p.id]" class="quantity-control"><button :aria-label="`Remove ${p.name}`" @click="shop.change(p.id, -1)"><Minus :size="12" /></button><span>{{ shop.cart.value[p.id] }}</span><button :aria-label="`Add ${p.name}`" :disabled="shop.cart.value[p.id] >= 10" @click="shop.change(p.id, 1)"><Plus :size="12" /></button></div><button v-else class="add-button" :aria-label="`Add ${p.name}`" @click="shop.change(p.id, 1)"><Plus :size="14" /></button></div></article></div></section>
    <section class="queue-section"><div class="section-heading"><h2>In good company.</h2><span class="queue-label"><span class="status-dot"></span>{{ shop.demo ? 'SAMPLE QUEUE' : 'RECENTLY LOCKED' }}</span></div><div class="queue-tags"><span v-for="(person, i) in (shop.demo ? [{ tag: '#A01', name: 'Amirul' }, { tag: '#A02', name: 'Nadia' }, { tag: '#A03', name: 'Wei' }] : queue)" :key="person.tag" class="queue-tag"><span :class="`avatar avatar-${i % 3}`">{{ person.name[0] }}</span><strong>{{ person.tag }}</strong> {{ person.name }}<Check :size="12" /></span><p v-if="!shop.demo && !queue.length" class="subtle">Be the first to lock a bottle for this drop.</p></div><p class="footer-note">Small batches. Happy desks. That’s the whole idea. <Leaf :size="13" /></p></section>
    <div class="order-bar"><div><small>{{ bottleCount(shop.cart.value) ? `${bottleCount(shop.cart.value)} BOTTLE${bottleCount(shop.cart.value) > 1 ? 'S' : ''} · ${chosen?.day.toUpperCase() || ''} DROP` : 'YOUR NEXT LITTLE PICK-ME-UP' }}</small><strong>{{ money(shop.amount.value) }}</strong></div><button class="primary" @click="checkout"><Zap :size="16" fill="currentColor" />LOCK MY BOTTLE<ArrowRight :size="17" /></button></div>
  </div>
</template>
